return "\n    #获取社团信息\n    get_family_data 31000 {\n        response {\n            familyid        0 : integer\n            rp_award        1 : boolean #奖励红点\n            rp_audit        2 : boolean #审批红点\n            next_apply_time 3 : integer #可以申请加入的时候（离开CD）\n            result          4 : integer #返回结果\n        }\n    }\n\n    #社团建筑信息\n    .family_building {\n        id 0 : integer #建筑id\n        lv 1 : integer #建筑等级\n    }\n\n    #获取社团基础信息\n    get_family_base_info 31001 {\n        response {\n            result          0  : integer # 0 未加入社团\n            familyid        1  : integer\n            familyname      2  : string\n            level           3  : integer\n            exp             4  : integer\n            money           5  : integer\n            notice          6  : string\n            tags            7  : integer\n            flag            8  : integer\n            threshold_type  9  : integer # 0 无要求 1 学籍 2 战力\n            threshold_value 10 : integer\n            audit_type      11 : integer # 0 符合条件进入 1 需要审核 2 禁止加入\n            active_weekly   12 : integer #社团周活跃值\n            award_flag      13 : integer #奖励领取情况\n            contribute      14 : integer #每日捐献\n            title           15 : integer\n            member          16 : integer #成员数量\n            buildings       17 : *family_building\n            slogan          18 : string\n        }\n    }\n\n    #获取社团成员列表\n    get_family_members 31002 {\n        request {\n            familyid 0 : integer\n        }\n        response {\n            .member {\n                playerid    0 : integer\n                name        1 : string\n                class       2 : integer\n                level       3 : integer\n                fightpower  4 : integer\n                head_sculpture      5 : integer #头像\n                lastlogin   6 : string  #-1 表示在线\n                active      7 : integer #七日贡献\n                title       8 : integer #职位\n                active_total 9 : integer #总贡献\n                star        10 : integer #全局星级\n            }\n            result  0 : integer\n            list    1 : *member\n        }\n    }\n\n    #获取社团的申请列表\n    get_family_applications 31003 {\n        response {\n            .family_application {\n                playerid    0 : integer\n                name        1 : string\n                class       2 : integer\n                level       3 : integer\n                fightpower  4 : integer\n                head_sculpture      5 : integer\n            }\n            result      0 : integer # 1 成功 11 未加入社团 12 权限不足\n            list        1 : *family_application\n        }\n    }\n\n    #审核社团申请\n    audit_family_application 31004 {\n        request {\n            ids     0 : *integer #处理的玩家id列表\n            type    1 : integer  #处理方式 1 忽略  2 接受\n        }\n        response {\n            result      0 : integer #1 不在社团中 2 没有审核权限 3 申请已被处理 4 社团满员\n            success_ids 1 : *integer #处理成功的id列表\n            member      2 : integer #成员数量\n            fullbreak   3 : boolean # true 社团满员中断\n        }\n    }\n\n    .family_guest_view {\n        familyid    0 : integer\n        familyname  1 : string\n        level       2 : integer\n        member      3 : integer #成员数量\n        flag        4 : integer\n        tags        5 : integer\n        active      6 : integer #七日活跃\n        slogan      7 : string\n        threshold_type  8 : integer\n        threshold_value 9 : integer\n        audit_type      10 : integer\n        max_member 11 : integer #最大成员数\n    }\n\n    #获取玩家申请列表\n    get_family_player_applications 31005 {\n        response {\n            .player_application {\n                family 0 : family_guest_view\n                status 1 : integer # 0 申请中 1 未通过\n            }\n            result  0 : integer # 1 成功\n            list    1 : *player_application\n        }\n    }\n\n    #申请加入社团\n    apply_join_family 31006 {\n        request {\n            familyid 0 : integer\n        }\n        response {\n            result  0 : integer #1成功 11 已加入社团 12 加入社团CD中 13 申请达到上限 14 社团不存在 15 不满足社团要求 16 社团禁止加入 17 社团满员 18 社团申请已满\n            type    1 : integer # 1 申请成功 2 加入成功\n        }\n    }\n\n    #取消社团申请\n    cancel_family_application 31007 {\n        request {\n            familyid 0 : integer\n        }\n        response {\n            result 0 : integer # 1成功\n        }\n    }\n\n    #搜索社团\n    search_family 31008 {\n        request {\n            word 0 : string\n            page 1 : integer\n        }\n        response {\n            result  0 : integer\n            remain  1 : integer\n            list    2 : *family_guest_view\n        }\n    }\n\n    #获取推荐列表\n    get_family_recommend_list 31009 {\n        response {\n            result  0 : integer\n            list    2 : *family_guest_view\n        }\n    }\n\n    #创建社团\n    create_family 31010 {\n        request {\n            familyname      0 : string\n            flag            1 : integer\n            threshold_type  2 : integer #加入条件 0 无要求 1 学籍 2 战力\n            threshold_value 3 : integer #门槛值\n            audit_type      4 : integer #审核类型 0 符合条件进入 1 需要审核 2 禁止加入\n        }\n        response {\n            result      0 : integer  #1 成功 2 名字不合法 3 物品不足 11 已加入社团 12 加入社团CD中 13 系统出错 14 社团名称重复\n            familyid    1 : integer\n            consumes    2 : *consumeids #消耗的物品\n            diamond     3 : integer #消耗的钻石\n        }\n    }\n\n    #社团信息设置\n    update_family_setting 31011 {\n        request {\n            .family_setting {\n                familyname  0 : string\n                flag        1 : integer\n                tags        2 : integer\n                slogan      3 : string\n                notice      4 : string\n                threshold_type  5 : integer\n                threshold_value 6 : integer\n                audit_type      7 : integer\n            }\n            familyid    0 : integer\n            setting     1 : family_setting\n        }\n        response {\n            result      0 : integer # 1 成功 2 物品不足 3 社团名称不合法 4 宣言不合法 5 社团公告不合法 11 不在社团中 12 权限不足 13 参数错误 14 社团名称重复\n            consumes    1 : *consumeids #消耗的物品\n            diamond     2 : integer #消耗的钻石\n        }\n    }\n\n    #离开社团\n    leave_family 31012 {\n        response {\n            result 0 : integer # 1 成功 11 社长不能离开社团\n        }\n    }\n\n    #踢出社团\n    kick_family_member 31013 {\n        request {\n            playerid 0 : integer\n        }\n        response {\n            result 0 : integer # 1 成功 11 没有加入社团 12 权限不足 13 玩家已经离开当前社团\n        }\n    }\n\n    #管理社团职务\n    manage_family_title 31014 {\n        request {\n            playerid    0 : integer\n            title       1 : integer\n        }\n        response {\n            result  0 : integer # 1 成功 11 不在社团中 12 对方不在社团中 13 权限不足 14 参数错误 15 该职位人数已满\n        }\n    }\n\n    #社团捐献\n    make_family_contribute 31015 {\n        request {\n            type 0 : integer\n        }\n        response {\n            result          0 : integer  # 1 成功 2 物品不足 3 参数错误  11 未加入社团 12 该档捐赠达到上限 13 改档捐赠次数已满\n            consumes        1 : *consumeids #消耗的物品\n            diamond_cost    2 : integer #消耗的钻石\n            gold_cost       3 : integer #消耗的金币\n            gold            4 : integer #获得的金币\n            diamond         5 : integer #获得的钻石\n            items           6 : *item #获取的物品\n        }\n    }\n\n    #领取社团活跃奖励\n    get_family_pt_reward 31016 {\n        request {\n            index 0 : integer\n        }\n        response {\n            result      0 : integer # 1成功 11 未加入社团 12 奖励已领取 13 参数错误 14 pt点不足\n            reward_flag 1 : integer\n            gold        2 : integer\n            diamond     3 : integer\n            items       4 : *item\n        }\n    }\n\n    #获取社团日志\n    get_family_log 31017 {\n        response {\n            .log {\n                id          0 : integer\n                time        1 : integer\n                playerid    2 : integer\n                nickname    3 : string\n                title       4 : integer\n                title_old   5 : integer\n                playerid2   6 : integer\n                nickname2   7 : string\n                title2      8 : integer\n                activityid  9 : integer\n            }\n            result  0 : integer # 1 成功\n            list    1 : *log\n        }\n    }\n\n    #获取社团历史聊天记录\n    get_family_chat_history 31018 {\n        request {\n            msgid 0 : integer\n        }\n        response {\n            .chat {\n                msgid 0 : integer\n                playerid 1 : integer\n                nickname 2 : string #昵称\n                head_sculpture 3 : integer #玩家头像\n                msg 4 : string #聊天内容\n                time 5 : integer #时间\n                class 6 : integer # 班级\n                level 7 : integer # 等级\n            }\n            result 0 : integer #1 成功 2 未加入社团\n            list 1 : *chat\n            more 2 : boolean #是否有更多\n        }\n    }\n\n    #社团聊天\n    family_chat 31019 {\n        request {\n            msg 0 : string\n        }\n        response {\n            result 0 : integer # 1 成功 2 未加入社团 3 禁言中 4 聊天消息非法\n        }\n    }\n\n    #升级社团建筑\n    family_building_levelup 31020 {\n        request {\n            id 0 : integer #建筑id\n        }\n        response {\n            result 0 : integer #1 成功 2 未加入社团 3 权限不足 4 社团资金不足 5 升级条件不满足\n            lv 1 : integer #建筑等级\n            familymoney 2 : integer #当前社团资金\n        }\n    }\n\n    #获取社团捐赠信息\n    get_family_contribute_info 31021 {\n        response {\n            .info {\n                id 0 : integer #挡位\n                count 1 : integer #已捐赠次数\n            }\n            result 0 : integer # 1 成功  2 未加入社团\n            list 1 : *info\n        }\n    }\n\n    #获取社团许愿板信息\n    get_family_wish_info 31022 {\n        response {\n            .info {\n                id          0 : integer     #唯一id       1\n                playerid    1 : integer     #玩家id       1   \n                wishid      2 : integer     #心愿id       1\n                count       3 : integer     #已被捐赠数量         1\n                name        4 : string      #玩家名称            \n                title       5 : integer     #社团职位\n                head_sculpture  6 : integer #玩家头像\n                is_friend   7 : boolean     #是否好友\n                wish_time   8 : integer     #心愿发布时间戳(秒)    1\n                finish_time 9 : integer     #每次捐赠时间戳(秒)    1\n            }\n            result 0 : integer # 1 成功\n            list 1 : *info      #许愿列表\n        }\n    }\n    \n    #获取社团许愿次数\n    get_family_wish_num 31023 {\n        response {\n            result              0 : integer     # 1 成功，2没有社团\n            family_wish_count   1 : integer     #常驻，今日已许愿次数\n            family_give_count   2 : integer     #常驻，今日已赠送次数\n            activity_wish_count 3 : integer     #活动，今日已许愿次数\n            activity_give_count 4 : integer     #活动，今日已赠送次数\n        }\n    }\n    \n    #许愿\n    do_family_wish_make 31024 {\n        request {\n            wishid 0 : integer #心愿id\n        }\n        response {\n            result 0 : integer # 1 成功，2没有社团，3非法数据，4未拥有指定道具，5该许愿项还未开始，6该许愿项已经结束，7今日常驻次数已用完，8今日活动次数已用完\n        }\n    }\n    \n    #赠送\n    do_family_wish_give 31025 {\n        request {\n            id 0 : integer #许愿唯一id\n        }\n        response {\n            result      0 : integer     # 1 成功，2没有社团，3非法数据，4心愿不存在，5该心愿已被达成，6无法对自己的心愿进行捐赠，7今日常驻捐赠次数已用完，8今日活动捐赠次数已用完，9道具数量不足，10等级不足\n            consumes    1 : *consumeids #消耗的物品\n            gold        2 : integer     #获得的金币\n            diamond     3 : integer     #获得的钻石\n            items       4 : *item       #获取的物品\n        }\n    }\n\n    #受赠记录\n    get_family_wish_record1 31026 {\n        response {\n            .info {\n                recordid    0 : integer     #记录唯一id\n                playerid    1 : integer     #赠送方玩家id\n                wishid      2 : integer     #心愿id\n                itemid      3 : integer     #捐赠道具id\n                itemnum     4 : integer     #捐赠道具数量\n                name        5 : string      #玩家名称\n                head_sculpture  6 : integer #玩家头像\n                record_time     7 : integer #记录时间戳(秒)\n                is_recv     8 : boolean     #是否已领取\n                is_thank    9 : boolean     #是否已感谢\n            }\n            result          0 : integer     # 1 成功，2没有社团\n            list            1 : *info       #受赠记录列表\n        }\n    }\n\n    #捐赠记录\n    get_family_wish_record2 31027 {\n        response {\n            .info {\n                recordid    0 : integer     #记录唯一id\n                playerid    1 : integer     #受赠方玩家id\n                wishid      2 : integer     #心愿id\n                itemid      3 : integer     #捐赠道具id\n                itemnum     4 : integer     #捐赠道具数量\n                name        5 : string      #玩家名称\n                head_sculpture  6 : integer #玩家头像\n                record_time     7 : integer #记录时间戳(秒)\n                is_recv     8 : boolean     #是否已收礼\n                can_recv    9 : boolean     #是否可以收礼\n            }\n            result          0 : integer     # 1 成功，2没有社团\n            list            1 : *info       #捐赠记录列表\n        }\n    }\n    \n    #领取&感谢&收礼\n    do_family_wish_other 31028 {\n        request {\n            recordid    0 : integer #记录唯一id\n            tp          1 : integer #1领取，2感谢，3收礼\n        }\n        response {\n            result      0 : integer # 1 成功，2没有社团，3找不到对应记录或已过期，4非法数据\n            gold        1 : integer #获得的金币\n            diamond     2 : integer #获得的钻石\n            items       3 : *item   #获取的物品\n        }\n    }\n\n"
